int r = 0, c = 0;
double minor[2][2];
for (int i = 0; i < 3; ++i) {
    if (i == row) continue;
    for (int j = 0; j < 3; ++j) {
        if (j == col) continue;
        minor[r][c] = m.data[i][j];
        ++c;
        if (c == 2) {
            c = 0;
            ++r;
        }
    }
}
double det = minor[0][0] * minor[1][1] - minor[0][1] * minor[1][0];
double sign = (row + col) % 2 == 0 ? 1.0 : -1.0;
return sign * det;

